  typedef enum logic [3:0] {
    APU_VN_FAULT_NONE = 0,
    APU_VN_FAULT_UNKNOWN_TYPE = 1,
    APU_VN_FAULT_STYPE = 2,
    APU_VN_FAULT_PNEXT = 3,
    APU_VN_FAULT_FLAGS = 4,
    APU_VN_FAULT_BOUND = 5,
    APU_VN_FAULT_HANDLE_ZERO = 6,
    APU_VN_FAULT_LOOP = 7,
    APU_VN_FAULT_ROM = 8,
    APU_VN_FAULT_PAYLOAD = 9
  } apu_vn_fault_e;

  typedef enum logic [2:0] {
    APU_VN_ROLE_LOOKUP = 0,
    APU_VN_ROLE_NEW = 1,
    APU_VN_ROLE_RETIRE = 2,
    APU_VN_ROLE_OPTIONAL = 3
  } apu_vn_role_e;

  typedef struct packed {
    logic [15:0] off;
    logic [16:0] words;
  } apu_vn_blob_t;

  typedef struct {
    logic [31:0] cmd_type;
    logic [31:0] cmd_flags;
    logic [63:0] q [8];
    logic [5:0]  qkind [8];
    logic [2:0]  qrole [8];
    logic [7:0]  qv;
    logic [31:0] imm [16];
    logic [15:0] immv;
    logic [31:0] cnt [4];
    apu_vn_blob_t blob [2];
    logic [7:0]  pres;
    logic [15:0] chain [8];
    logic [3:0]  chain_n;
    logic [5:0]  obj_kind;
    logic [7:0]  reply_prog;
    logic [15:0] words;
    apu_vn_fault_e fault;
    logic [15:0] fault_word;
    logic [31:0] fault_val;
    logic [15:0] pay_words;
  } apu_vn_op_t;

endpackage
